local TrophyMaker = {}
local PRODUCTS = {
    simple_bronze_trophy = { name = "Preprosta bronasta trofeja", bronzeCost = 2, marbleCost = 1, time = 4, cost = 80, beauty = 22, prestige = 4, happiness = 2, description = "Preprosta bronasta trofeja za zmagovalce." },
    silver_cup_trophy = { name = "Srebrni pokal trofeja", silverCost = 2, bronzeCost = 1, marbleCost = 1, time = 7, cost = 220, beauty = 38, prestige = 10, happiness = 3, description = "Srebrni pokal trofeja za trgovce." },
    gold_chalice_trophy = { name = "Zlati kelih trofeja", goldCost = 2, silverCost = 1, bronzeCost = 1, marbleCost = 1, time = 11, cost = 540, beauty = 52, prestige = 18, happiness = 4, description = "Zlati kelih trofeja za plemiče." },
    jewel_crowned_trophy = { name = "Draguljnookronana trofeja", goldCost = 2, silverCost = 1, bronzeCost = 1, marbleCost = 1, jewelCost = 1, time = 15, cost = 1300, beauty = 68, prestige = 30, happiness = 6, description = "Trofeja z draguljno krono za visoke plemiče." },
    pearl_set_grand_trophy = { name = "Bisernavi velika trofeja", goldCost = 3, silverCost = 2, bronzeCost = 1, marbleCost = 1, jewelCost = 1, pearlCost = 1, time = 19, cost = 2900, beauty = 82, prestige = 45, happiness = 8, description = "Velika trofeja z biseri za visoko plemstvo." },
    royal_grand_trophy = { name = "Kraljevski veliki trofeja", goldCost = 4, silverCost = 2, bronzeCost = 1, marbleCost = 2, jewelCost = 2, pearlCost = 2, time = 26, cost = 6500, beauty = 95, prestige = 75, happiness = 13, description = "Velika kraljevska trofeja z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    trophy_workshop = { name = "Trofejna delavnica", cost = { gold = 280, wood = 100, stone = 140, bronze = 6 }, upkeep = 6, qualityBonus = 5 },
    engravers_loft = { name = "Graverska podstrešje", cost = { gold = 1000, wood = 240, stone = 280, silver = 6, marble = 4 }, upkeep = 23, qualityBonus = 18 },
    master_trophy_atelier = { name = "Mojstrski trofejni atelje", cost = { gold = 2800, wood = 360, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_trophy_palace = { name = "Kraljevska trofejna palača", cost = { gold = 12000, wood = 580, stone = 760, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
TrophyMaker.bronzeStock = 14; TrophyMaker.marbleStock = 12; TrophyMaker.silverStock = 8; TrophyMaker.goldStock = 6; TrophyMaker.jewelStock = 4; TrophyMaker.pearlStock = 4
TrophyMaker.productStock = {}; TrophyMaker.buildings = {}; TrophyMaker.maker = nil; TrophyMaker.activeMaking = {}; TrophyMaker.totalProducts = 0; TrophyMaker.dayTimer = 0
function TrophyMaker.init() TrophyMaker.bronzeStock=14; TrophyMaker.marbleStock=12; TrophyMaker.silverStock=8; TrophyMaker.goldStock=6; TrophyMaker.jewelStock=4; TrophyMaker.pearlStock=4; TrophyMaker.productStock={}; TrophyMaker.buildings={}; TrophyMaker.maker=nil; TrophyMaker.activeMaking={}; TrophyMaker.totalProducts=0; TrophyMaker.dayTimer=0; print("[TrophyMaker] Royal Trophy Maker System initialized (6 products, 4 buildings)") end
function TrophyMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TrophyMaker.maker={name=n or ("Trofejar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Trofejar najet: %s (spretnost: %d)",TrophyMaker.maker.name,s),"success") end; return true end
function TrophyMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TrophyMaker.build(id) local ok,e=TrophyMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TrophyMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TrophyMaker.getQualityBonus() local b=0; for _,bd in ipairs(TrophyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TrophyMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.bronzeCost and TrophyMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.marbleCost and TrophyMaker.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.silverCost and TrophyMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TrophyMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TrophyMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TrophyMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TrophyMaker.buildings==0 then return false,"Potrebna trofejna delavnica" end; if not TrophyMaker.maker then return false,"Potreben trofejar" end; return true end
function TrophyMaker.make(pt,qty) qty=qty or 1; local ok,e=TrophyMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.bronzeCost then TrophyMaker.bronzeStock=TrophyMaker.bronzeStock-d.bronzeCost*qty end; if d.marbleCost then TrophyMaker.marbleStock=TrophyMaker.marbleStock-d.marbleCost*qty end; if d.silverCost then TrophyMaker.silverStock=TrophyMaker.silverStock-d.silverCost*qty end; if d.goldCost then TrophyMaker.goldStock=TrophyMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TrophyMaker.jewelStock=TrophyMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TrophyMaker.pearlStock=TrophyMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TrophyMaker.maker then t=math.max(1,t-math.floor(TrophyMaker.maker.skill/12)) end; table.insert(TrophyMaker.activeMaking,{id="trophy_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TrophyMaker.completeMaking(m) local q=1.0+(TrophyMaker.getQualityBonus()/100); if TrophyMaker.maker then q=q+(TrophyMaker.maker.skill/140) end; q=math.min(2.5,q); TrophyMaker.productStock[m.productType]=(TrophyMaker.productStock[m.productType] or 0)+m.quantity; TrophyMaker.totalProducts=TrophyMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TrophyMaker.maker then TrophyMaker.maker.itemsMade=TrophyMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TrophyMaker.maker.skill=math.min(100,TrophyMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Trofeja izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"trophy.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function TrophyMaker.update(dt) if not _G.state then return end; TrophyMaker.dayTimer=TrophyMaker.dayTimer+dt; if TrophyMaker.dayTimer>=30 then TrophyMaker.dayTimer=0; for i=#TrophyMaker.activeMaking,1,-1 do local m=TrophyMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TrophyMaker.completeMaking(m); table.remove(TrophyMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TrophyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TrophyMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TrophyMaker.getStats() return {bronzeStock=TrophyMaker.bronzeStock,marbleStock=TrophyMaker.marbleStock,silverStock=TrophyMaker.silverStock,goldStock=TrophyMaker.goldStock,jewelStock=TrophyMaker.jewelStock,pearlStock=TrophyMaker.pearlStock,productStock=TrophyMaker.productStock,numBuildings=#TrophyMaker.buildings,hasMaker=TrophyMaker.maker~=nil,makerName=TrophyMaker.maker and TrophyMaker.maker.name or "—",makerSkill=TrophyMaker.maker and TrophyMaker.maker.skill or 0,activeMaking=#TrophyMaker.activeMaking,totalProducts=TrophyMaker.totalProducts} end
return TrophyMaker
